import pandas as pd

# File paths for all source tables
source_files = [
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_32/training_0.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_32/training_1.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_32/training_2.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_32/training_3.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_32/training_4.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_32/training_5.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_32/training_6.csv",
    "autopipeline-benchmarks/github-pipelines/intermediate_space/length6_32/training_7.csv",
]

# Read all source tables with index_col=0 to ignore the numerical index column
dfs = [pd.read_csv(f, index_col=0) for f in source_files]

# Concatenate all source tables (UNION)
df = pd.concat(dfs, ignore_index=True)

# Convert 'created' column to string without timezone info (remove timezone if present)
# Some source 'created' columns have timezone info, target examples do not.
df['created'] = pd.to_datetime(df['created'], errors='coerce').dt.strftime('%Y-%m-%d %H:%M:%S')

# Ensure 'screenname' is string
df['screenname'] = df['screenname'].astype(str)

# Ensure 'followers' and 'favourites' are integers
df['followers'] = pd.to_numeric(df['followers'], errors='coerce').fillna(0).astype(int)
df['favourites'] = pd.to_numeric(df['favourites'], errors='coerce').fillna(0).astype(int)

# Ensure 'text' column is string type (decode bytes if needed)
# The source 'text' column contains byte literals (e.g. b'...'), so decode them.
def decode_text(x):
    if isinstance(x, bytes):
        try:
            return x.decode('utf-8', errors='replace')
        except Exception:
            return str(x)
    elif isinstance(x, str):
        # Sometimes the string looks like b'...' literal, remove leading b' and trailing '
        if x.startswith("b'") or x.startswith('b"'):
            try:
                # Evaluate the literal bytes string safely
                return eval(x).decode('utf-8', errors='replace')
            except Exception:
                return x
        else:
            return x
    else:
        return str(x)

df['text'] = df['text'].apply(decode_text)

# Reorder columns to match target schema exactly
df = df[['created', 'screenname', 'followers', 'favourites', 'text']]

# Write the final target table to the specified path without the index
df.to_csv("autopipeline-benchmarks/github-pipelines/length6_32/target_multisource.csv", index=False)
